import itertools

def calculate_sumset_size(T):
    """Calculates the size of the sum set T+T = {t_i + t_j | 0 <= i <= j <= N-1}"""
    N = len(T)
    sums = set()
    for i in range(N):
        for j in range(i, N):
            sums.add(T[i] + T[j])
    return len(sums)

